const precondition = {
  root: read("pre-root", root, "fontSize", 0),
  nodes: nodes.map((node, index) => read("pre-node", node, "fontSize", index + 1)),
  rootAnimations: root.getAnimations().length,
  nodeAnimations: nodes.map(node => node.getAnimations().length),
};
root.classList.add("active");

assert_equals(precondition.root, mode === "animated" ? "23px" : "32px", "pre-styled root");
assert_array_equals(precondition.nodes, Array(depth).fill("11px"), "all descendants pre-styled");
assert_equals(precondition.rootAnimations, 0, "no pre-existing root animation");
assert_array_equals(precondition.nodeAnimations, Array(depth).fill(0), "no pre-existing child animations");
